module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  localparam PTR_BITS = (DEPTH <= 1) ? 1 : $clog2(DEPTH);

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [PTR_BITS-1:0] wptr;
  reg [PTR_BITS-1:0] rptr;
  reg [PTR_BITS:0] count;

  wire wr_ok = wr_en && !full;
  wire rd_ok = rd_en && !empty;

  assign full = (count == DEPTH);
  assign empty = (count == 0);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wptr <= {PTR_BITS{1'b0}};
      rptr <= {PTR_BITS{1'b0}};
      count <= {(PTR_BITS+1){1'b0}};
      dout <= {WIDTH{1'b0}};
    end else begin
      if (wr_ok) begin
        mem[wptr] <= din;
        wptr <= (wptr + 1'b1) & (DEPTH - 1);
      end

      if (rd_ok) begin
        dout <= mem[rptr];
        rptr <= (rptr + 1'b1) & (DEPTH - 1);
      end

      if (wr_ok && !rd_ok) begin
        count <= count + 1'b1;
      end else if (rd_ok && !wr_ok) begin
        count <= count - 1'b1;
      end
    end
  end

endmodule
